macro_rules! impl_122 {
    () => {
        deps!();
        impl < 'a > DFA < & 'a [u8] > { # [doc = " Safely deserialize a sparse DFA with a specific state identifier"] # [doc = " representation. Upon success, this returns both the deserialized DFA"] # [doc = " and the number of bytes read from the given slice. Namely, the contents"] # [doc = " of the slice beyond the DFA are not read."] # [doc = ""] # [doc = " Deserializing a DFA using this routine will never allocate heap memory."] # [doc = " For safety purposes, the DFA's transitions will be verified such that"] # [doc = " every transition points to a valid state. If this verification is too"] # [doc = " costly, then a [`DFA::from_bytes_unchecked`] API is provided, which"] # [doc = " will always execute in constant time."] # [doc = ""] # [doc = " The bytes given must be generated by one of the serialization APIs"] # [doc = " of a `DFA` using a semver compatible release of this crate. Those"] # [doc = " include:"] # [doc = ""] # [doc = " * [`DFA::to_bytes_little_endian`]"] # [doc = " * [`DFA::to_bytes_big_endian`]"] # [doc = " * [`DFA::to_bytes_native_endian`]"] # [doc = " * [`DFA::write_to_little_endian`]"] # [doc = " * [`DFA::write_to_big_endian`]"] # [doc = " * [`DFA::write_to_native_endian`]"] # [doc = ""] # [doc = " The `to_bytes` methods allocate and return a `Vec<u8>` for you. The"] # [doc = " `write_to` methods do not allocate and write to an existing slice"] # [doc = " (which may be on the stack). Since deserialization always uses the"] # [doc = " native endianness of the target platform, the serialization API you use"] # [doc = " should match the endianness of the target platform. (It's often a good"] # [doc = " idea to generate serialized DFAs for both forms of endianness and then"] # [doc = " load the correct one based on endianness.)"] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " Generally speaking, it's easier to state the conditions in which an"] # [doc = " error is _not_ returned. All of the following must be true:"] # [doc = ""] # [doc = " * The bytes given must be produced by one of the serialization APIs"] # [doc = "   on this DFA, as mentioned above."] # [doc = " * The endianness of the target platform matches the endianness used to"] # [doc = "   serialized the provided DFA."] # [doc = ""] # [doc = " If any of the above are not true, then an error will be returned."] # [doc = ""] # [doc = " Note that unlike deserializing a [`dense::DFA`], deserializing a sparse"] # [doc = " DFA has no alignment requirements. That is, an alignment of `1` is"] # [doc = " valid."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " This routine will never panic for any input."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This example shows how to serialize a DFA to raw bytes, deserialize it"] # [doc = " and then use it for searching."] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{dfa::{Automaton, sparse::DFA}, HalfMatch, Input};"] # [doc = ""] # [doc = " let initial = DFA::new(\"foo[0-9]+\")?;"] # [doc = " let bytes = initial.to_bytes_native_endian();"] # [doc = " let dfa: DFA<&[u8]> = DFA::from_bytes(&bytes)?.0;"] # [doc = ""] # [doc = " let expected = Some(HalfMatch::must(0, 8));"] # [doc = " assert_eq!(expected, dfa.try_search_fwd(&Input::new(\"foo12345\"))?);"] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " # Example: loading a DFA from static memory"] # [doc = ""] # [doc = " One use case this library supports is the ability to serialize a"] # [doc = " DFA to disk and then use `include_bytes!` to store it in a compiled"] # [doc = " Rust program. Those bytes can then be cheaply deserialized into a"] # [doc = " `DFA` structure at runtime and used for searching without having to"] # [doc = " re-compile the DFA (which can be quite costly)."] # [doc = ""] # [doc = " We can show this in two parts. The first part is serializing the DFA to"] # [doc = " a file:"] # [doc = ""] # [doc = " ```no_run"] # [doc = " use regex_automata::dfa::sparse::DFA;"] # [doc = ""] # [doc = " let dfa = DFA::new(\"foo[0-9]+\")?;"] # [doc = ""] # [doc = " // Write a big endian serialized version of this DFA to a file."] # [doc = " let bytes = dfa.to_bytes_big_endian();"] # [doc = " std::fs::write(\"foo.bigendian.dfa\", &bytes)?;"] # [doc = ""] # [doc = " // Do it again, but this time for little endian."] # [doc = " let bytes = dfa.to_bytes_little_endian();"] # [doc = " std::fs::write(\"foo.littleendian.dfa\", &bytes)?;"] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " And now the second part is embedding the DFA into the compiled program"] # [doc = " and deserializing it at runtime on first use. We use conditional"] # [doc = " compilation to choose the correct endianness. We do not need to employ"] # [doc = " any special tricks to ensure a proper alignment, since a sparse DFA has"] # [doc = " no alignment requirements."] # [doc = ""] # [doc = " ```no_run"] # [doc = " use regex_automata::{"] # [doc = "     dfa::{Automaton, sparse::DFA},"] # [doc = "     util::lazy::Lazy,"] # [doc = "     HalfMatch, Input,"] # [doc = " };"] # [doc = ""] # [doc = " // This crate provides its own \"lazy\" type, kind of like"] # [doc = " // lazy_static! or once_cell::sync::Lazy. But it works in no-alloc"] # [doc = " // no-std environments and let's us write this using completely"] # [doc = " // safe code."] # [doc = " static RE: Lazy<DFA<&'static [u8]>> = Lazy::new(|| {"] # [doc = "     # const _: &str = stringify! {"] # [doc = "     #[cfg(target_endian = \"big\")]"] # [doc = "     static BYTES: &[u8] = include_bytes!(\"foo.bigendian.dfa\");"] # [doc = "     #[cfg(target_endian = \"little\")]"] # [doc = "     static BYTES: &[u8] = include_bytes!(\"foo.littleendian.dfa\");"] # [doc = "     # };"] # [doc = "     # static BYTES: &[u8] = b\"\";"] # [doc = ""] # [doc = "     let (dfa, _) = DFA::from_bytes(BYTES)"] # [doc = "         .expect(\"serialized DFA should be valid\");"] # [doc = "     dfa"] # [doc = " });"] # [doc = ""] # [doc = " let expected = Ok(Some(HalfMatch::must(0, 8)));"] # [doc = " assert_eq!(expected, RE.try_search_fwd(&Input::new(\"foo12345\")));"] # [doc = " ```"] # [doc = ""] # [doc = " Alternatively, consider using"] # [doc = " [`lazy_static`](https://crates.io/crates/lazy_static)"] # [doc = " or"] # [doc = " [`once_cell`](https://crates.io/crates/once_cell),"] # [doc = " which will guarantee safety for you."] pub fn from_bytes (slice : & 'a [u8] ,) -> Result < (DFA < & 'a [u8] > , usize) , DeserializeError > { let (dfa , nread) = unsafe { DFA :: from_bytes_unchecked (slice) ? } ; let seen = dfa . tt . validate (& dfa . special) ? ; dfa . st . validate (& dfa . special , & seen) ? ; Ok ((dfa , nread)) } # [doc = " Deserialize a DFA with a specific state identifier representation in"] # [doc = " constant time by omitting the verification of the validity of the"] # [doc = " sparse transitions."] # [doc = ""] # [doc = " This is just like [`DFA::from_bytes`], except it can potentially return"] # [doc = " a DFA that exhibits undefined behavior if its transitions contains"] # [doc = " invalid state identifiers."] # [doc = ""] # [doc = " This routine is useful if you need to deserialize a DFA cheaply and"] # [doc = " cannot afford the transition validation performed by `from_bytes`."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " This routine is not safe because it permits callers to provide"] # [doc = " arbitrary transitions with possibly incorrect state identifiers. While"] # [doc = " the various serialization routines will never return an incorrect"] # [doc = " DFA, there is no guarantee that the bytes provided here are correct."] # [doc = " While `from_bytes_unchecked` will still do several forms of basic"] # [doc = " validation, this routine does not check that the transitions themselves"] # [doc = " are correct. Given an incorrect transition table, it is possible for"] # [doc = " the search routines to access out-of-bounds memory because of explicit"] # [doc = " bounds check elision."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{dfa::{Automaton, sparse::DFA}, HalfMatch, Input};"] # [doc = ""] # [doc = " let initial = DFA::new(\"foo[0-9]+\")?;"] # [doc = " let bytes = initial.to_bytes_native_endian();"] # [doc = " // SAFETY: This is guaranteed to be safe since the bytes given come"] # [doc = " // directly from a compatible serialization routine."] # [doc = " let dfa: DFA<&[u8]> = unsafe { DFA::from_bytes_unchecked(&bytes)?.0 };"] # [doc = ""] # [doc = " let expected = Some(HalfMatch::must(0, 8));"] # [doc = " assert_eq!(expected, dfa.try_search_fwd(&Input::new(\"foo12345\"))?);"] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] pub unsafe fn from_bytes_unchecked (slice : & 'a [u8] ,) -> Result < (DFA < & 'a [u8] > , usize) , DeserializeError > { let mut nr = 0 ; nr += wire :: read_label (& slice [nr ..] , LABEL) ? ; nr += wire :: read_endianness_check (& slice [nr ..]) ? ; nr += wire :: read_version (& slice [nr ..] , VERSION) ? ; let _unused = wire :: try_read_u32 (& slice [nr ..] , "unused space") ? ; nr += size_of :: < u32 > () ; let (flags , nread) = Flags :: from_bytes (& slice [nr ..]) ? ; nr += nread ; let (tt , nread) = Transitions :: from_bytes_unchecked (& slice [nr ..]) ? ; nr += nread ; let (st , nread) = StartTable :: from_bytes_unchecked (& slice [nr ..]) ? ; nr += nread ; let (special , nread) = Special :: from_bytes (& slice [nr ..]) ? ; nr += nread ; if special . max . as_usize () >= tt . sparse () . len () { return Err (DeserializeError :: generic ("max should not be greater than or equal to sparse bytes" ,)) ; } let (quitset , nread) = ByteSet :: from_bytes (& slice [nr ..]) ? ; nr += nread ; let pre = None ; Ok ((DFA { tt , st , special , pre , quitset , flags } , nr)) } }
    };
}

impl_122!()